#!/usr/bin/env bash
# SPDX-License-Identifier: GPL-3.0-only
#
# The scored file's record, after the file was rebuilt at a committed tree.
# One commit. Additive; nothing is rewritten. Not pushed.
#
# Runs the licence gate first and stops if it fails; the change is a report
# that no test reads, regenerated by its own generator from the manifest, so
# the suite and the lint are not run here.

set -euo pipefail
cd "$(dirname "$0")/.."

say() { printf '\n== %s\n' "$1"; }

if [ ! -f LICENSE ] || [ ! -f pyproject.toml ]; then
    echo "Run this from the repository, not from somewhere else."
    exit 1
fi

say "the report records the rebuild at the committed tree"
if ! grep -q 'ce78d8f4c8aa60ff11b78302245ba1f6fa16f6ec' reports/submission-2026-09-19.md; then
    echo "reports/submission-2026-09-19.md does not name revision ce78d8f"
    exit 1
fi
if ! grep -q '| tree clean at the build | true |' reports/submission-2026-09-19.md; then
    echo "reports/submission-2026-09-19.md does not record a clean tree"
    exit 1
fi
if ! grep -q '73cccbd64ae8976afa22f2856f21528b2c44fead1d76c743200592847b1df6ac' \
        reports/submission-2026-09-19.md; then
    echo "reports/submission-2026-09-19.md does not carry the file's sha256"
    exit 1
fi
echo "ok"

say "the report is changed, and nothing else beyond the next script's own files"
# The external-data review (scripts/commit_external_data_review.sh, run after
# this one) may already be in the tree; nothing else may be.
changed="$(git -c core.fileMode=false status --short \
    | grep -v -e '^?? scripts/commit_submission_rebuild.sh$' \
              -e '^?? scripts/commit_external_data_review.sh$' \
              -e '^ M README.md$' -e '^ M docs/paper.md$' -e '^ M docs/prior_art.md$' || true)"
if [ "$changed" != " M reports/submission-2026-09-19.md" ]; then
    echo "unexpected working-tree state:"
    git -c core.fileMode=false status --short
    exit 1
fi
echo "ok"

say "the report is newer than its generators"
for gen in scripts/report_submission.py scripts/make_submission.py; do
    if [ "$gen" -nt reports/submission-2026-09-19.md ]; then
        echo "reports/submission-2026-09-19.md is older than $gen -- regenerate it"
        exit 1
    fi
done
echo "ok"

say "licence gate"
python3 scripts/check_licence_hygiene.py

say "commit"
git add reports/submission-2026-09-19.md scripts/commit_submission_rebuild.sh
git commit -q -F - <<'MSG'
Record the scored file rebuilt at the committed tree

The file recorded on 19 September was built from an uncommitted tree
over 9af7e2e, so its manifest named a revision that held none of the
code that built it. Rebuilt twice at ce78d8f, with the tree clean, it is
byte for byte the same file: sha256 73cccbd6..., 1,491,042 bytes, 107
record-quality rows, all in January. The report now records that
revision, the clean tree, and the two builds' times. Nothing has been
uploaded.
MSG

say "result"
git --no-pager log --oneline -3
echo
git -c core.fileMode=false status --short
echo
echo "Not pushed."
